#!/usr/bin/env node

// Kaki Rally Raid — deterministic surface field contract.
//
// A 24 km stage is streamed as independent sectors generated by workers in an
// arbitrary order. That only produces a seamless world if the field is a pure
// function of world metres. These assertions are the regression guard on that
// property, including far from the origin where float error would show first.

import assert from 'node:assert/strict';

import {
  RAID_MAX_LATTICE,
  RAID_SURFACES,
  RAID_SURFACE_ORDER,
  RAID_ZONE_ORDER,
  blendRaidZones,
  classifyRaidSurface,
  fbm,
  getRaidZone,
  gradientNoise,
  raidLooseness,
  raidSurfaceByIndex,
  raidSurfaceIndex,
  raidTerrainHeight,
  raidTerrainNormal,
  ridgedNoise,
} from '../src/racing/raid/raidSurfaceField.js';

// The sector grid the streaming provider uses. Sector size and cell size are
// powers of two, so every vertex world coordinate is an exact integer at any
// distance from the origin and boundary samples cannot disagree by float error.
const SECTOR_METRES = 512;
const SECTOR_CELLS = 256;
const CELL_METRES = SECTOR_METRES / SECTOR_CELLS;

const SEED = 0x4b41524d;
const WIND = 0.7853981633974483;

let checks = 0;
function pass(message) {
  checks += 1;
  console.log(`  PASS  ${message}`);
}

const params = blendRaidZones('dune-sea', 'rock-shelf', 0.35);

// ---------------------------------------------------------------------------
assert.equal(CELL_METRES, 2, 'sector cell size must stay an exact power of two');
for (const sector of [0, 1, -1, 23, -17, 240]) {
  for (const cell of [0, 1, 128, 255, 256]) {
    const world = sector * SECTOR_METRES + cell * CELL_METRES;
    assert.equal(world, Math.trunc(world), `vertex world coordinate is not exact: ${world}`);
    assert(Number.isSafeInteger(world), `vertex world coordinate is not a safe integer: ${world}`);
  }
}
pass('sector vertex world coordinates are exact integers at every sector index');

// ---------------------------------------------------------------------------
// Purity: the field must not depend on call order, warm-up, or neighbouring
// evaluations. Interleaving two very different positions must not perturb them.
{
  const a = raidTerrainHeight(137.5, -4210.25, params, SEED, WIND);
  const b = raidTerrainHeight(19831, 7742, params, SEED, WIND);
  const aAgain = raidTerrainHeight(137.5, -4210.25, params, SEED, WIND);
  for (let i = 0; i < 64; i += 1) raidTerrainHeight(i * 13.7, i * -9.1, params, SEED, WIND);
  const aFinal = raidTerrainHeight(137.5, -4210.25, params, SEED, WIND);
  const bFinal = raidTerrainHeight(19831, 7742, params, SEED, WIND);
  assert.equal(a, aAgain, 'height changed when re-evaluated');
  assert.equal(a, aFinal, 'height changed after unrelated evaluations');
  assert.equal(b, bFinal, 'height changed after unrelated evaluations');
}
pass('terrain height is a pure function of position, seed, and zone parameters');

// ---------------------------------------------------------------------------
// Seam equality. For every adjacent sector pair the shared edge must agree
// exactly, both as float64 and as the float32 actually stored and uploaded.
function edgeSamples(sectorX, sectorZ, params_) {
  const east = new Float64Array(SECTOR_CELLS + 1);
  const west = new Float64Array(SECTOR_CELLS + 1);
  const originX = sectorX * SECTOR_METRES;
  const originZ = sectorZ * SECTOR_METRES;
  for (let row = 0; row <= SECTOR_CELLS; row += 1) {
    const worldZ = originZ + row * CELL_METRES;
    // Rightmost column of this sector.
    east[row] = raidTerrainHeight(originX + SECTOR_METRES, worldZ, params_, SEED, WIND);
    // Leftmost column of the sector to the east, evaluated from its own origin.
    west[row] = raidTerrainHeight((sectorX + 1) * SECTOR_METRES, worldZ, params_, SEED, WIND);
  }
  return { east, west };
}

const SEAM_SECTORS = [
  [0, 0], [1, 0], [-1, 3], [7, -2],
  // ~12 km and ~24 km from the origin: where precision-driven seams appear.
  [23, -17], [24, -17], [46, 41], [-47, -40],
];
let seamSamples = 0;
for (const [sx, sz] of SEAM_SECTORS) {
  const { east, west } = edgeSamples(sx, sz, params);
  for (let row = 0; row <= SECTOR_CELLS; row += 1) {
    assert.equal(east[row], west[row], `float64 seam mismatch at sector ${sx},${sz} row ${row}`);
    assert.equal(
      Math.fround(east[row]),
      Math.fround(west[row]),
      `float32 seam mismatch at sector ${sx},${sz} row ${row}`,
    );
    seamSamples += 1;
  }
}
pass(`adjacent sector edges are bit-identical near and far from the origin (${seamSamples} shared vertices, out to 24 km)`);

// ---------------------------------------------------------------------------
// Normals must also agree across a boundary, or the wheel contact normal steps.
{
  const worldX = 23 * SECTOR_METRES + SECTOR_METRES;
  let maxDelta = 0;
  for (let row = 0; row <= SECTOR_CELLS; row += 8) {
    const worldZ = -17 * SECTOR_METRES + row * CELL_METRES;
    const a = raidTerrainNormal(worldX, worldZ, params, SEED, WIND);
    const b = raidTerrainNormal(worldX, worldZ, params, SEED, WIND, 0.75, { x: 0, y: 1, z: 0 });
    maxDelta = Math.max(maxDelta, Math.abs(a.x - b.x), Math.abs(a.y - b.y), Math.abs(a.z - b.z));
    assert(Number.isFinite(a.x) && Number.isFinite(a.y) && Number.isFinite(a.z), 'normal is not finite');
    assert(a.y > 0, 'terrain normal points downward');
  }
  assert.equal(maxDelta, 0, 'terrain normal is not reproducible across evaluations');
}
pass('terrain normals are finite, upward, and reproducible on a sector boundary');

// ---------------------------------------------------------------------------
// Lattice bound: the highest-frequency octave must stay far inside int32.
{
  const extremeMetres = 240 * SECTOR_METRES; // ~123 km, far beyond any stage.
  let maxLattice = 0;
  for (const zoneId of RAID_ZONE_ORDER) {
    const zone = getRaidZone(zoneId);
    const smallestScale = Math.min(zone.detailScale, zone.macroScale, zone.ridgeWavelength, 74);
    // Three octaves above the base at lacunarity ~2.13.
    const highestFrequency = Math.pow(2.13, 3) / smallestScale;
    maxLattice = Math.max(maxLattice, Math.abs(extremeMetres * highestFrequency));
  }
  assert(
    maxLattice < RAID_MAX_LATTICE,
    `lattice index ${maxLattice} exceeds the safe bound ${RAID_MAX_LATTICE}`,
  );
  assert(maxLattice < 2 ** 24, `lattice index ${maxLattice} loses float precision`);
}
pass('noise lattice indices stay well inside int32 and float precision out to 123 km');

// ---------------------------------------------------------------------------
// Range and finiteness across every zone.
{
  for (const zoneId of RAID_ZONE_ORDER) {
    const zoneParams = blendRaidZones(zoneId, zoneId, 0);
    let minimum = Infinity;
    let maximum = -Infinity;
    for (let i = 0; i < 4000; i += 1) {
      const x = ((i * 2654435761) % 40000) - 20000 + (i % 7) * 0.25;
      const z = ((i * 40503) % 40000) - 20000 + (i % 5) * 0.5;
      const height = raidTerrainHeight(x, z, zoneParams, SEED, WIND);
      assert(Number.isFinite(height), `${zoneId} produced a non-finite height at ${x},${z}`);
      minimum = Math.min(minimum, height);
      maximum = Math.max(maximum, height);
    }
    const zone = getRaidZone(zoneId);
    const bound = zone.macroHeight + zone.ridgeHeight + zone.detailHeight * (1 + zone.rockiness * 4.2) + 2;
    assert(
      Math.abs(minimum) <= bound && Math.abs(maximum) <= bound,
      `${zoneId} exceeded its expected relief bound: ${minimum.toFixed(2)}..${maximum.toFixed(2)} vs ${bound.toFixed(2)}`,
    );
    assert(maximum - minimum > 0.5, `${zoneId} is suspiciously flat: ${(maximum - minimum).toFixed(3)} m of relief`);
  }
}
pass(`every terrain zone stays finite and inside its declared relief bound (${RAID_ZONE_ORDER.length} zones)`);

// ---------------------------------------------------------------------------
// Zone blending must be continuous: no relief discontinuity mid-transition.
{
  const x = 4820;
  const z = -1337;
  let previous = raidTerrainHeight(x, z, blendRaidZones('dune-sea', 'wadi-gravel', 0), SEED, WIND);
  let maxStep = 0;
  for (let step = 1; step <= 200; step += 1) {
    const t = step / 200;
    const height = raidTerrainHeight(x, z, blendRaidZones('dune-sea', 'wadi-gravel', t), SEED, WIND);
    maxStep = Math.max(maxStep, Math.abs(height - previous));
    previous = height;
  }
  assert(maxStep < 0.6, `zone blend steps ${maxStep.toFixed(3)} m per 0.5% of the transition`);
}
pass('zone blending changes relief continuously rather than switching biome abruptly');

// ---------------------------------------------------------------------------
// Surface tables must be complete and round-trip through their packed index.
{
  for (const id of RAID_SURFACE_ORDER) {
    const surface = RAID_SURFACES[id];
    assert(surface, `surface table is missing ${id}`);
    for (const key of ['grip', 'drag', 'sinkage', 'roughness', 'momentum', 'dust', 'tyreWear', 'punctureRisk']) {
      assert(Number.isFinite(surface[key]), `${id}.${key} is not finite`);
    }
    assert.equal(raidSurfaceByIndex(raidSurfaceIndex(id)).id, id, `${id} does not round-trip through its index`);
  }
  // Momentum recovery must be ordered the way the discipline claims: salt is
  // the fastest surface to catch a slide on, powder the slowest.
  const momentum = RAID_SURFACE_ORDER.map((id) => RAID_SURFACES[id].momentum);
  assert.equal(Math.max(...momentum), RAID_SURFACES.salt.momentum, 'salt is not the highest-momentum surface');
  assert.equal(Math.min(...momentum), RAID_SURFACES.powder.momentum, 'powder is not the lowest-momentum surface');
  assert(RAID_SURFACES.rock.punctureRisk > RAID_SURFACES.loose.punctureRisk * 5, 'rock is not meaningfully more puncturing than sand');
}
pass(`surface table is complete and physically ordered (${RAID_SURFACE_ORDER.length} surfaces)`);

// ---------------------------------------------------------------------------
// Classification must be deterministic and produce more than one identity.
{
  const observed = new Set();
  for (const zoneId of RAID_ZONE_ORDER) {
    const zoneParams = blendRaidZones(zoneId, zoneId, 0);
    for (let i = 0; i < 900; i += 1) {
      const x = ((i * 7919) % 9000) - 4500;
      const z = ((i * 104729) % 9000) - 4500;
      const relief = fbm(x / 240, z / 240, SEED, 2);
      const id = classifyRaidSurface(x, z, zoneParams, SEED, { relief, slope: Math.abs(relief) * 0.6 });
      const again = classifyRaidSurface(x, z, zoneParams, SEED, { relief, slope: Math.abs(relief) * 0.6 });
      assert.equal(id, again, 'surface classification is not deterministic');
      assert(RAID_SURFACES[id], `classification produced an unknown surface: ${id}`);
      observed.add(id);
      const looseness = raidLooseness(x, z, zoneParams, SEED, relief);
      assert(looseness >= 0 && looseness <= 1, `looseness out of range: ${looseness}`);
    }
  }
  assert(observed.size >= 5, `classification only produced ${observed.size} surfaces across every zone`);
}
pass(`surface classification is deterministic and varied (${RAID_SURFACE_ORDER.length} surfaces reachable)`);

// ---------------------------------------------------------------------------
// Noise primitives: range, determinism, and continuity.
{
  for (let i = 0; i < 2000; i += 1) {
    const x = (i * 0.37) - 370;
    const z = (i * -0.53) + 211;
    const g = gradientNoise(x, z, SEED);
    const f = fbm(x, z, SEED, 5);
    const r = ridgedNoise(x, z, SEED, 4);
    assert(g >= -1 && g <= 1, `gradientNoise out of range: ${g}`);
    assert(f >= -1.001 && f <= 1.001, `fbm out of range: ${f}`);
    assert(r >= -1.001 && r <= 1.001, `ridgedNoise out of range: ${r}`);
  }
  // Continuity across a lattice line: gradient noise is zero-crossing at
  // integers, so the step across one must stay small.
  let maxStep = 0;
  let previous = gradientNoise(99.99, 12.34, SEED);
  for (let i = 1; i <= 40; i += 1) {
    const value = gradientNoise(99.99 + i * 0.001, 12.34, SEED);
    maxStep = Math.max(maxStep, Math.abs(value - previous));
    previous = value;
  }
  assert(maxStep < 0.05, `gradient noise steps ${maxStep.toFixed(4)} across a lattice line`);
}
pass('noise primitives stay in range, deterministic, and continuous across lattice lines');

console.log(`\nKaki Rally Raid surface field passed: ${checks} contracts, ${seamSamples} seam vertices verified`);
